-- Generated by scripts/build-chapter-assessments.mjs from n5-b03.json.
-- Add missing identity-card evidence and a concrete final communication task.
-- Source IDs, choices, answer keys, lesson IDs and frozen attempts stay intact.
CREATE TABLE IF NOT EXISTS n5_assessment_support_backup_181 (
  lesson_id UUID PRIMARY KEY,
  before_lesson JSONB NOT NULL,
  before_questions JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

DO $support$
DECLARE
  target UUID;
  targets INTEGER;
  revision JSONB;
  plan JSONB := '[{"id":"b04c8420-fd02-37fe-840f-fdaa7c59bea6","key":"b03-a-v04","question":"Kartu Deni: pekerjaan = perawat. Lengkapi perkenalan profesinya: デニさんは（　）です。"},{"id":"efaeb15e-5eea-322a-94e4-1a30041eabbf","key":"b03-b-v04","question":"Kartu Mina: kewarganegaraan = Jepang. Lengkapi perkenalannya: ミナさんは（　）です。"}]'::jsonb;
BEGIN
  SELECT count(*), (array_agg(l.id))[1] INTO targets, target
    FROM lessons l JOIN modules m ON m.id = l.module_id
    JOIN courses c ON c.id = m.course_id
    WHERE c.slug = 'n5' AND m.slug = 'n5-b3'
      AND l.slug = 'assignment-bab-3-perkenalan' AND l.type = 'quiz';
  IF targets <> 1 THEN
    RAISE EXCEPTION '181: expected one N5 Bab 3 assignment, found %', targets;
  END IF;
  PERFORM 1 FROM lessons WHERE id = target FOR UPDATE;
  -- A repeat preserves both the original backup and subsequent admin edits.
  IF EXISTS (SELECT 1 FROM n5_assessment_support_backup_181 WHERE lesson_id = target) THEN RETURN; END IF;
  IF (SELECT assessment_policy->>'version' FROM lessons WHERE id = target) IS DISTINCT FROM 'n5-assessment-v2' THEN
    RAISE EXCEPTION '181: unexpected Bab 3 assessment version';
  END IF;
  FOR revision IN SELECT value FROM jsonb_array_elements(plan) LOOP
    PERFORM 1 FROM quiz_questions q
      WHERE q.id = (revision->>'id')::uuid AND q.lesson_id = target
        AND q.assessment_meta->>'key' = revision->>'key'
        AND q.assessment_meta->>'version' = 'n5-assessment-v2'
      FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '181: missing or changed source question %', revision->>'key'; END IF;
  END LOOP;
  INSERT INTO n5_assessment_support_backup_181(lesson_id, before_lesson, before_questions)
    SELECT target, to_jsonb(l), (
      SELECT jsonb_agg(to_jsonb(q) || jsonb_build_object('options', (
        SELECT jsonb_agg(to_jsonb(o) ORDER BY o.sort_order, o.id)
          FROM quiz_options o WHERE o.question_id = q.id
      )) ORDER BY q.sort_order, q.id)
      FROM quiz_questions q
      WHERE q.lesson_id = target AND q.id IN (
        SELECT (value->>'id')::uuid FROM jsonb_array_elements(plan)
      )
    ) FROM lessons l WHERE l.id = target;

  FOR revision IN SELECT value FROM jsonb_array_elements(plan) LOOP
    UPDATE quiz_questions SET question = revision->>'question'
      WHERE id = (revision->>'id')::uuid AND lesson_id = target;
  END LOOP;
  UPDATE lessons SET assessment_policy = jsonb_set(assessment_policy, '{transferTask}', '{"title":"Perkenalan dan percakapan pertama","prompt":"Tulis lalu ucapkan perkenalan 4–5 kalimat. Setelah itu, buat percakapan 4–6 giliran bersama teman atau mainkan kedua peran sendiri. Gunakan kartu Rina dan Dodi di bawah atau data diri dengan kosakata Bab 3. Tinjau hasilnya memakai empat kriteria; latihan ini tidak menambah atau mengurangi nilai kuis.","steps":["Perkenalan: sampaikan nama, negara, status atau pekerjaan, lalu 1–2 informasi keluarga. Gunakan 4–5 kalimat pendek; salam pembuka dan penutup boleh ditambahkan.","Percakapan: saling berkenalan, temukan satu kesamaan dengan も, tanyakan status atau pekerjaan dengan ですか, lalu jawab sesuai kartu. Salah satu pertanyaan menebak pekerjaan yang keliru agar jawabannya memakai じゃありません atau ではありません dan menyebut pekerjaan yang benar.","Ulangi dengan data berbeda dari kosakata Bab 3. Gunakan ね untuk memastikan informasi yang sudah didengar atau よ untuk memberi informasi baru bila situasinya sesuai. Keduanya tidak harus muncul dalam setiap perkenalan."],"roleCards":[{"role":"A","name":"Rina","facts":"Indonesia; pelajar; ayah guru; ibu perawat."},{"role":"B","name":"Dodi","facts":"Indonesia; insinyur; bukan pelajar."}],"exampleIntroduction":"わたしは リナです。インドネシアじんです。がくせいです。ちちは せんせいです。ははは かんごしです。","exampleDialogue":["A: はじめまして。リナです。インドネシアじんです。","B: はじめまして。ドディです。わたしも インドネシアじんです。","A: ドディさんは がくせいですか。","B: いいえ、がくせいじゃありません。エンジニアです。リナさんは がくせいですか。","A: はい、がくせいです。","B: どうぞよろしくおねがいします。"],"rubric":["Informasi: nama, negara, pekerjaan atau status, dan keluarga sesuai kartu atau data yang dipilih.","Tata bahasa: gunakan は…です, ですか, dan bentuk negatif sesuai maksud; も menyatakan kesamaan yang sudah memiliki acuan. Jika memakai の, ね, atau よ, hubungan dan konteksnya tepat.","Respons: jawaban menjawab pertanyaan yang diajukan; dugaan yang keliru dikoreksi dengan informasi yang benar.","Keterpahaman: tulisan dapat dibaca dan ujaran dapat dipahami. Jeda atau kesalahan kecil yang tidak mengubah maksud masih dapat diterima."],"rubricScale":["2 — Terpenuhi secara mandiri dan maknanya jelas.","1 — Sebagian terpenuhi; masih perlu petunjuk atau satu perbaikan.","0 — Belum terlihat atau maknanya berbeda dari yang diminta."],"acceptedVariations":"じゃありません dan ではありません sama-sama diterima. Topik yang sudah jelas boleh tidak diulang. Nama sendiri tidak memakai さん. Jawaban tidak harus sama persis dengan contoh; nilai informasi dan maksudnya."}'::jsonb, true),
    updated_at = NOW() WHERE id = target;
END;
$support$;
